-- c011-v001: dan–raja Salomo mengasihi perempuan-perempuan asing banyak dan– anak perempuan– Firaun orang Moab orang Amon orang Edom orang Sidon orang Het
-- c011-v002: dari– bangsa-bangsa yang berfirman– TUHAN kepada– anak-anak Israel tidak– kamu masuk di antara mereka dan mereka tidak– mereka masuk di antaramu pasti mereka memalingkan – hatimu mengikuti allah-allah mereka kepada mereka melekat Salomo untuk–mengasihi
-- c011-v003: dan adalah– baginya istri-istri permaisuri tujuh ratus dan selir-selir tiga ratus dan memalingkan istri-istrinya – hatinya
-- c011-v004: dan terjadilah pada waktu hari tua Salomo istri-istrinya memalingkan – hatinya mengikuti allah-allah lain dan tidak– adalah hatinya sempurna dengan– TUHAN Allahnya seperti hati Daud ayahnya
-- c011-v005: dan pergilah Salomo mengikuti Asytoret allah orang Sidon dan mengikuti Milkom kekejian orang Amon
-- c011-v006: dan melakukan Salomo yang jahat di mata TUHAN dan tidak mengikut sepenuhnya mengikuti TUHAN seperti Daud ayahnya 
-- c011-v007: lalu dibangun Salomo bukit pengorbanan untuk Kamos kekejian Moab di gunung yang di– sebelah timur Yerusalem dan untuk Molokh kekejian anak-anak Amon
-- c011-v008: dan demikian ia lakukan untuk semua– istri-istrinya yang asing yang membakar kemenyan dan mempersembahkan korban kepada allah-allah mereka
-- c011-v009: dan menjadi murka TUHAN kepada Salomo karena– berpaling hatinya dari pada TUHAN Allah Israel yang menampakkan diri kepadanya dua kali
-- c011-v010: dan memerintahkan kepadanya tentang– hal ini supaya–jangan– pergi mengikuti allah-allah lain tetapi tidak ia menaati – yang– diperintahkan TUHAN 
-- c011-v011: dan berfirmanlah TUHAN kepada Salomo oleh karena yang adalah– ini bersamamu dan tidak engkau menaati perjanjian-Ku dan ketetapan-ketetapan-Ku yang Aku perintahkan kepadamu sungguh-sungguh Aku akan merobek – kerajaan daripadamu dan Aku akan memberikannya kepada hambamu
-- c011-v012: tetapi– dalam hari-harimu tidak Aku akan melakukannya demi Daud ayahmu dari tangan anakmu Aku akan merobeknya
-- c011-v013: hanya – seluruh– kerajaan tidak Aku akan merobek suku satu Aku akan berikan kepada anakmu demi Daud hamba-Ku dan demi Yerusalem yang Aku pilih
-- c011-v014: dan membangkitkan TUHAN lawan bagi Salomo – Hadad orang Edom dari keturunan raja dia di Edom
-- c011-v015: dan terjadilah ketika berada Daud di– Edom ketika naik Yoab panglima tentara untuk menguburkan – orang-orang yang terbunuh dan membunuh semua– laki-laki di Edom
-- c011-v016: karena enam bulan tinggal– di sana Yoab dan seluruh– Israel sampai– ia melenyapkan semua– laki-laki di Edom
-- c011-v017: dan melarikan diri Hadad dia dan orang-orang Edom dari hamba-hamba ayahnya bersamanya untuk pergi Mesir dan Hadad pemuda kecil
-- c011-v018: dan berangkatlah mereka dari Midian dan datang Paran dan membawa orang-orang bersama mereka dari Paran dan datang Mesir kepada– Firaun raja– Mesir dan memberikan– kepadanya rumah dan makanan berkata kepadanya dan tanah diberikan kepadanya
-- c011-v019: dan mendapat Hadad kasih karunia di mata Firaun sangat dan memberikan– kepadanya istri – saudara perempuan istrinya saudara perempuan Tahpenes ratu
-- c011-v020: dan melahirkan kepadanya saudara perempuan Tahpenes – Genubat anaknya dan menyapihnya Tahpenes di tengah-tengah rumah Firaun dan adalah Genubat rumah Firaun di tengah-tengah anak-anak Firaun
-- c011-v021: dan Hadad mendengar di Mesir bahwa– berbaring Daud dengan– nenek moyangnya dan bahwa– mati Yoab panglima– tentara dan berkatalah Hadad kepada– Firaun biarkanlah aku pergi dan aku akan pergi ke– negeriku
-- c011-v022: dan berkatalah kepadanya Firaun karena apa– engkau kekurangan bersamaku dan lihatlah engkau meminta untuk pergi ke– negerimu dan berkatalah tidak tetapi sungguh-sungguh biarkanlah aku pergi
-- c011-v023: dan membangkitkan Allah baginya lawan – Rezon anak– Elyada yang melarikan diri dari Hadadezer raja– Zoba tuannya
-- c011-v024: dan mengumpulkan kepadanya orang-orang dan menjadi kepala– gerombolan ketika membunuh Daud mereka dan pergi Damsyik dan tinggal di dalamnya dan memerintah di Damsyik
-- c011-v025: dan menjadi lawan bagi Israel sepanjang– hari-hari Salomo dan– kejahatan yang Hadad dan membenci Israel dan memerintah atas– Aram 
-- c011-v026: dan Yerobeam anak– Nebat orang Efrata dari– Zereda dan nama ibunya Zerua perempuan janda hamba Salomo dan mengangkat tangan melawan raja
-- c011-v027: dan ini alasan yang– mengangkat tangan melawan raja Salomo membangun – Milo menutup – lobang tembok kota Daud ayahnya
-- c011-v028: dan orang Yerobeam pahlawan gagah perkasa dan melihat Salomo – pemuda bahwa– melakukan pekerjaan dia dan mengangkat dia atas semua– kerja rodi kaum Yusuf 
-- c011-v029: dan terjadilah pada waktu itu dan Yerobeam keluar dari Yerusalem dan menjumpai dia Ahia orang Silo nabi di jalan dan dia berselubung dengan jubah baru dan keduanya sendirian di padang
-- c011-v030: dan meraih Ahia jubah baru yang ada padanya dan merobeknya dua belas koyakan
-- c011-v031: dan berkatalah kepada Yerobeam ambillah– bagimu sepuluh koyakan karena demikian berfirman TUHAN Allah Israel sesungguhnya Aku merobek – kerajaan dari tangan Salomo dan Aku akan memberikan kepadamu – sepuluh suku
-- c011-v032: dan suku satu akan menjadi– baginya demi hamba-Ku Daud dan demi Yerusalem kota yang Aku pilih di dalamnya dari semua suku-suku Israel
-- c011-v033: oleh karena yang mereka meninggalkan Aku dan menyembah kepada Asytoret allah orang Sidon kepada Kamos allah Moab dan kepada Milkom allah anak-anak– Amon dan tidak– mereka berjalan di jalan-jalan-Ku untuk melakukan yang benar di mata-Ku dan ketetapan-ketetapan-Ku dan peraturan-peraturan-Ku seperti Daud ayahnya
-- c011-v034: dan tidak– Aku akan mengambil – seluruh– kerajaan dari tangannya karena pemimpin Aku akan menempatkannya sepanjang hari-hari hidupnya demi Daud hamba-Ku yang Aku pilih dia yang menaati perintah-perintah-Ku dan ketetapan-ketetapan-Ku
-- c011-v035: dan Aku akan mengambil kerajaan dari tangan anaknya dan Aku akan memberikannya kepadamu – sepuluh suku
-- c011-v036: dan kepada anaknya Aku akan berikan suku– satu supaya ada– pelita bagi Daud– hamba-Ku sepanjang– hari-hari di hadapan-Ku di Yerusalem kota yang Aku pilih bagi-Ku untuk menaruh nama-Ku di sana
-- c011-v037: dan engkau Aku akan ambil dan engkau akan memerintah atas semua yang– diinginkan jiwamu dan engkau akan menjadi raja atas– Israel
-- c011-v038: dan terjadilah jika– engkau mendengarkan – semua– yang Aku perintahkan kepadamu dan engkau berjalan di jalan-jalan-Ku dan engkau melakukan yang benar di mata-Ku untuk memelihara ketetapan-ketetapan-Ku dan perintah-perintah-Ku sebagaimana melakukan Daud hamba-Ku dan Aku akan menyertai engkau dan Aku akan membangun bagimu keluarga– yang teguh sebagaimana Aku membangun bagi Daud dan Aku akan memberikan kepadamu – Israel
-- c011-v039: dan Aku akan merendahkan – keturunan Daud karena ini tetapi tidak sepanjang– hari-hari 
-- c011-v040: dan mencari Salomo untuk membunuh – Yerobeam dan bangkitlah Yerobeam dan melarikan diri Mesir kepada– Sisak raja– Mesir dan tinggal di Mesir sampai– kematian Salomo
-- c011-v041: dan sisa perbuatan Salomo dan segala– yang ia lakukan dan hikmatnya bukankah– itu tertulis dalam– kitab riwayat Salomo
-- c011-v042: dan hari-hari yang memerintah Salomo di Yerusalem atas– seluruh– Israel empat puluh tahun
